WITH unpacked AS (SELECT id, service, level, latency_ms, payload_json, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier, COALESCE(context['trace'], 'unknown') AS trace_or_default FROM app_logs WHERE service = 'checkout') SELECT level, CASE WHEN latency_ms >= 2256 THEN 'HIGH' ELSE 'LOW' END AS latency_ms_tier, BIT_OR(latency_ms) AS latency_ms_bit_or, PERCENTILE_APPROX(latency_ms, 0.95) AS latency_ms_p95, AVG(latency_ms) FILTER (WHERE service = 'auth') AS auth_avg_latency_ms, PERCENTILE_APPROX(latency_ms, 0.9) AS latency_ms_p90 FROM unpacked GROUP BY ROLLUP (level, CASE WHEN latency_ms >= 2256 THEN 'HIGH' ELSE 'LOW' END)
